  padding: 3rem 0;
}

.fleet-layout {
  display: grid;
  grid-template-columns: 260px 1fr;
  gap: 1.5rem;
}

.fleet-list, .fleet-card {
  background: #fff;
  border: 1px solid rgba(8, 43, 63, 0.1);
  border-radius: 22px;
  padding: 1rem;
  box-shadow: 0 16px 40px rgba(8, 43, 63, 0.06);
}

.fleet-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  align-self: start;
}

.fleet-list-item {
  border: 1px solid rgba(8, 43, 63, 0.12);
  border-radius: 14px;
  padding: 0.85rem;
  background: #fff;
  text-align: left;
  cursor: pointer;
}

.fleet-list-item.active {
  border-color: #bf8b40;
  background: #fff8ef;
}

.fleet-list-item strong, .fleet-list-item small {
  display: block;
}

.fleet-list-item small {
  color: #6d7887;
}

.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 1rem;
}

label {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  font-weight: 600;
  color: #082b3f;
}

input {
  border: 1px solid rgba(8, 43, 63, 0.16);
  border-radius: 12px;
  padding: 0.75rem 0.85rem;
  font: inherit;
}

.checkbox-line {
  flex-direction: row;
  align-items: center;
}

.actions {
  margin-top: 1.25rem;
}

.success {
  color: #17633a;
  font-weight: 700;
}

.error {
  color: #b42318;
  font-weight: 700;
}

@media (max-width: 900px) {
  .fleet-layout {
    grid-template-columns: 1fr;
  }
